#!/usr/bin/env node
// Offline import only. Run with node --import tsx scripts/import-echelonsix-release.mjs [assemble|verify].
// assemble refuses to overwrite; verify compares every generated byte and exact file set.
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { isDeepStrictEqual } from 'node:util';
import { getAllCourses } from '../shared/courseRegistry.ts';
import { interactiveModes, interactivePackageSchema } from '../server/interactiveContent/schema.ts';
import { legalScreen, missingAuthorityEvidenceIds } from './echelonsix-legal-screen.mjs';

const candidate = '/home/ubuntu/outputs/echelon-six-games-2026-11-12/final-candidate';
const output = path.resolve('server/interactiveContent/release-2026-11-12');
const metadataHash = '934304ad19093615fcfa2202e81ad6a7e22a142849dc1fb104a1454ceaa8f97b';
const digest = b => createHash('sha256').update(b).digest('hex');
const stringify = x => `${JSON.stringify(x, null, 2)}\n`;
const fail = m => { throw new Error(m); };
const read = p => { if (!fs.lstatSync(p).isFile()) fail(`Not a regular file: ${p}`); return fs.readFileSync(p); };
const equal = (a,b,message) => { if (!isDeepStrictEqual(a,b)) fail(message); };
const sorted = a => [...a].sort();
const checkRef = ref => { const b = read(ref.path); if (digest(b) !== ref.sha256) fail(`Hash mismatch: ${ref.path}`); return b; };

function run(verify) {
  const metaBytes = read(`${candidate}/server-only-metadata.json`);
  if (digest(metaBytes) !== metadataHash) fail('Candidate metadata hash mismatch');
  const meta = JSON.parse(metaBytes);
  const keys = sorted(getAllCourses().filter(c => c.isActive && c.track !== 'construction-electrician').map(c => c.courseKey));
  const rows = [...meta.courses].sort((a,b) => a.courseKey.localeCompare(b.courseKey));
  equal(sorted(rows.map(r => r.courseKey)), keys, 'Candidate keys do not match canonical courses');
  if (keys.length !== 38 || keys.some(k => /309/i.test(k))) fail('Unexpected course scope');
  if (meta.counts.courses !== 38 || meta.counts.examples !== 3984) fail('Unexpected candidate counts');
  const files = new Map();
  files.set('evidence/candidate-metadata.json', metaBytes);
  // Preserve original evidence and exclusions, separately from the payload. Their
  // historical candidate-only status is not an assertion about this registration.
  const evidenceNames = new Set(['release-scope-report.md', 'manifest.tsv', 'excluded-items.json', 'build-release-scope.py']);
  for (const ref of meta.priorReports) if (evidenceNames.has(path.basename(ref.path))) files.set(`evidence/${path.basename(ref.path)}`, checkRef(ref));
  if (files.size !== 5) fail('Missing release scope evidence');
  const exclusions = JSON.parse(files.get('evidence/excluded-items.json'));
  if (exclusions.length !== 73) fail('Unexpected excluded item count');
  const excludedIds = new Set(exclusions.map(x => x.item.id));
  if (excludedIds.size !== 73) fail('Duplicate excluded IDs');
  const allIds = new Set(); const totals = Object.fromEntries(interactiveModes.map(m => [m, 0]));
  const releaseRows = []; const additionalExclusions = []; const screenManifest = [];
  for (const row of rows) {
    const key = row.courseKey;
    for (const ref of row.reviewReferences) checkRef(ref);
    const source = checkRef(row.source);
    const pkgBytes = checkRef(row.package), provBytes = checkRef(row.provenance);
    const pkg = JSON.parse(pkgBytes), prov = JSON.parse(provBytes);
    if (pkg.status !== 'draft' || pkg.courseKey !== key || prov.packageSha256 !== digest(pkgBytes) || prov.source.sha256 !== digest(source)) fail(`Candidate mismatch: ${key}`);
    equal(Buffer.from(prov.source.originalBytes, 'base64'), source, `Source preservation mismatch: ${key}`);
    equal(pkg.previewIds, row.previewIds, `Preview mismatch: ${key}`);
    if (pkg.examples.length !== row.itemCount) fail(`Count mismatch: ${key}`);
    const originals = JSON.parse(source);
    const originalById = new Map(originals.map(x => [x.id, x]));
    if (originalById.size !== originals.length || originals.length !== pkg.examples.length) fail(`Source IDs invalid: ${key}`);
    const kept = [];
    for (const item of pkg.examples) {
      const original = originalById.get(item.id);
      if (!original || item.mode !== original.mode || allIds.has(item.id) || excludedIds.has(item.id) || /309/i.test(item.id)) fail(`Excluded/duplicate/missing item: ${item.id}`);
      allIds.add(item.id);
      const reasons = legalScreen(original);
      if (reasons.length) additionalExclusions.push({ courseKey: key, reasons, original, converted: item });
      else { kept.push(item); totals[item.mode]++; }
    }
    const previewIds = {};
    for (const mode of interactiveModes) {
      const ids = sorted(kept.filter(x => x.mode === mode).map(x => x.id));
      if (ids.length < 2) fail(`Insufficient retained mode coverage: ${key}/${mode}`);
      previewIds[mode] = ids[0];
    }
    // Approval is software eligibility only; no human or technical validation is asserted.
    const released = { ...pkg, status: 'approved', previewIds, examples: kept };
    screenManifest.push({ courseKey: key, before: pkg.examples.length, after: kept.length, excluded: pkg.examples.length - kept.length, modeCounts: Object.fromEntries(interactiveModes.map(mode => [mode, kept.filter(x => x.mode === mode).length])) });
    const parsed = interactivePackageSchema.safeParse(released);
    if (!parsed.success) fail(`Runtime schema rejected ${key}: ${JSON.stringify(parsed.error.issues)}`);
    const releaseBytes = Buffer.from(stringify(released));
    files.set(`packages/${key}.json`, releaseBytes);
    files.set(`provenance/${key}.json`, provBytes);
    releaseRows.push({ courseKey: key, sourceSha256: row.source.sha256, candidatePackageSha256: row.package.sha256, provenanceSha256: row.provenance.sha256, releasedPackageSha256: digest(releaseBytes), itemCount: kept.length, previewIds });
  }
  if (allIds.size !== 3984) fail('Candidate item count mismatch');
  const counts = { courses: rows.length, examples: Object.values(totals).reduce((a,b) => a+b,0), modes: totals };
  equal(counts, { courses: 38, examples: 3821, modes: { 'rapid-swipe': 701, 'speed-match': 389, 'odd-one-out': 521, 'cause-effect': 987, 'tap-the-flaw': 656, 'before-after': 567 } }, 'Unexpected retained release counts');
  if (additionalExclusions.length !== 163) fail('Unexpected additional exclusion count');
  equal(sorted(additionalExclusions.filter(x => x.reasons.includes('excluded-missing-authority-evidence')).map(x => x.original.id)), sorted(missingAuthorityEvidenceIds), 'Missing authority-evidence exclusions');
  files.set('evidence/additional-exclusions.json', Buffer.from(stringify(additionalExclusions)));
  files.set('evidence/additional-screen-manifest.json', Buffer.from(stringify(screenManifest)));
  files.set('evidence/additional-screen-rules.mjs', read(path.resolve('scripts/echelonsix-legal-screen.mjs')));
  const imports = rows.map((r,i) => `import p${i} from './packages/${r.courseKey}.json';`).join('\n');
  const entries = rows.map((r,i) => `  '${r.courseKey}': { approved: true, content: p${i} },`).join('\n');
  files.set('registry.ts', Buffer.from(`// Generated by scripts/import-echelonsix-release.mjs; server-only.\n// Approval here means software release eligibility, not human technical review.\n${imports}\n\nexport const releasePackages: Readonly<Record<string, { approved: boolean; content: unknown }>> = Object.freeze({\n${entries}\n});\n`));
  files.set('release-metadata.json', Buffer.from(stringify({ format: 'echelon-six-games-server-release-v2', visibility: 'server-only; content and provenance contain answers', contentAuthorship: 'AI-authored', review: meta.review, limitations: meta.limitations + ' A conservative deterministic legal-language screen and explicit ID exclusions cannot prove all requirements were identified or verify safety or correctness. The content authority gate in docs/production-release-gate.md applies to content stating legal or regulatory requirements; the course page labels these activities as exam practice, not operating instructions or regulatory advice, and states that progress is not saved.', releaseEligibility: 'User authorized games registration, not deployment. Approved is a software flag, not human review or regulatory approval.', candidateMetadataSha256: metadataHash, previewSelection: 'Lexicographically smallest retained ID of the same mode.', exclusions: `73 historical exclusions plus ${additionalExclusions.length} additional conservative screen exclusions (156 prior plus 7 excluded for missing authority evidence); full originals and converted items are in server-only evidence.`, screenDecisions: [
    { id: 'class1-water-dist-074', decision: 'excluded', rationale: 'The answer and explanation imply mandatory backflow protection under an applicable standard without verified jurisdiction-specific authority; excluded for missing authority evidence, not a factual verdict.' },
    { id: 'wqa-023', decision: 'retained', rationale: 'The item identifies headings of numbered WHMIS safety data sheet sections; it does not state a legal requirement. This is not a determination that WHMIS has no legal requirements or independent verification of the headings.' },
    ...missingAuthorityEvidenceIds.map(id => ({ id, decision: 'excluded', rationale: 'Excluded for missing authority evidence: an OSHA-linked legal or site-program control obligation lacks verified jurisdiction-specific authority evidence. This is not a factual verdict.' })),
  ], counts, courses: releaseRows })));
  files.set('README.md', Buffer.from(`# Server-only six-game registration

Packages and evidence contain answers and must remain server-only. The release retains 3,821 items across all 38 courses and all six modes, with at least two items per course/mode and globally unique IDs. The 3,984-item pinned candidate has 163 additional screen exclusions: the prior 156 plus exactly seven excluded for missing authority evidence. The 73 historical exclusions remain separate and unchanged.

These items were AI-authored and prior research/review stages include AI factual review against primary sources; item-level records vary in scope and limitations. These are AI reviews, not human subject-matter sign-off or independent guarantees of accuracy, source currency, jurisdiction, safety, or instructional quality. This importer performs structural and deterministic screening checks only. Software status approved is not technical approval, regulatory approval, deployment authorization, or evidence of release-gate compliance.

The conservative deterministic screen retains its legal/authority terminology, regulatory-source safety-duty indicators, six manually flagged IDs, and the item-specific exclusion for class1-water-dist-074. It does not remove an item solely for the word must or an OSHA source URL. Class1-water-dist-074 remains excluded for an unverified mandatory backflow standard claim. Wqa-023 remains retained because it identifies WHMIS safety data sheet section headings, not a legal requirement; this does not assert WHMIS has no legal requirements or independently verify the headings. The screen can remove neutral examples with legal wording and cannot establish that all indirect claims have been found.

Exactly seven further IDs are excluded for missing authority evidence: wpi-class1-water-dist-078, wpi-class2-water-dist-055, wpi-class4-water-dist-055, wpi-class3-water-072, wpi-class3-water-dist-057, wpi-class1-water-coll-065, and us-class1-water-072. Their OSHA-linked legal or site-program control obligations lack verified jurisdiction-specific authority evidence; exclusion is not a factual verdict. Only the affected tap-the-flaw preview for wpi-class1-water-coll changes, from wpi-class1-water-coll-065 to wpi-class1-water-coll-066, the lowest retained matching-mode ID.

The actual content authority gate in [docs/production-release-gate.md](../../../docs/production-release-gate.md) applies to instructional content stating a legal or regulatory requirement: it requires jurisdiction, source URL, exact section or schedule where applicable, review date, and technical reviewer. Content without that evidence must be labelled exam guidance or field practice, not regulation. The course page identifies the exercises as interactive exam practice and provides the learner-facing label "Exam practice, not operating instructions or regulatory advice" in its practice-details disclosure. The disclosure summary states that progress is not saved before the activity boundary. These labels do not constitute human technical approval or prove that the deterministic screen found every indirect legal claim.

Historical pinned candidate metadata, original research, source bytes, provenance, and prior evidence remain unchanged. Provenance records all candidate items, including later exclusions. Additional exclusion evidence records complete original and converted item objects and deterministic reasons; the manifest records retained mode counts. All 38 registrations remain in place.

Reproduce from the repository root, with original pinned candidate and referenced sources available: \`env -i PATH="$PATH" HOME=/tmp NODE_ENV=test node --require ./scripts/test-safety.cjs --import tsx scripts/import-echelonsix-release.mjs verify\`. For fresh assembly move this directory to a preserved backup outside the generated directory, then run the same isolated command with \`assemble\`; the importer refuses overwrite. No network, database, browser, or deployment is involved.
`));
  if (!verify && fs.existsSync(output)) fail('Output exists; refusing to overwrite');
  if (verify) {
    const walk = d => fs.readdirSync(d, { withFileTypes: true }).flatMap(e => e.isDirectory() ? walk(path.join(d,e.name)) : [path.relative(output,path.join(d,e.name)).replaceAll('\\','/')]);
    equal(sorted(walk(output)), sorted(files.keys()), 'Unexpected generated file set');
    for (const [name, bytes] of files) equal(read(path.join(output,name)), bytes, `Generated file mismatch: ${name}`);
  } else {
    const stage = `${output}.tmp-${process.pid}`;
    if (fs.existsSync(stage)) fail('Temporary output already exists');
    try { fs.mkdirSync(stage, { recursive: false }); for (const [name, bytes] of files) { const dest = path.join(stage,name); fs.mkdirSync(path.dirname(dest), { recursive: true }); fs.writeFileSync(dest, bytes, { flag: 'wx' }); } fs.renameSync(stage,output); }
    catch (e) { fs.rmSync(stage, { recursive: true, force: true }); throw e; }
  }
  console.log(stringify({ operation: verify ? 'verify' : 'assemble', valid: true, output, counts, additionalExclusions: additionalExclusions.length }));
}
try { const cmd = process.argv[2] ?? 'verify'; if (!['assemble','verify'].includes(cmd) || process.argv.length > 3) fail('Usage: import-echelonsix-release.mjs [assemble|verify]'); run(cmd === 'verify'); } catch (e) { console.error(`Error: ${e.message}`); process.exitCode = 1; }
